CREATE OR REPLACE FUNCTION lr_serverless_aws_us_catalog.bricksurance_model.fn_champion_score(in_subject_kind STRING COMMENT 'Subject kind, one of POLICY, QUOTE, CLAIM, PARTY.', in_subject_id STRING COMMENT 'Identifier of the scored subject.')
RETURNS DECIMAL(12,6)
COMMENT 'The latest score from the champion model version for a given subject, derived live - never a stored balance. Lets any workbench ask ''what does the model in force say about this policy/quote/claim'' without knowing which version that is. Returns: Latest champion score for the subject; empty if none scored.'
RETURN (SELECT ms.score
 FROM lr_serverless_aws_us_catalog.bricksurance_model.model_score ms
 JOIN lr_serverless_aws_us_catalog.bricksurance_model.model_version mv ON mv.model_version_id = ms.model_version_id
 WHERE mv.model_status_code = 'CHAMPION'
   AND ms.subject_kind_code = in_subject_kind
   AND ms.subject_id = in_subject_id
 ORDER BY ms.scored_at DESC
 LIMIT 1);
